"use client";
import React, { useState } from "react";
import { ShieldCheck, Watch, Footprints, Shirt, Info, Diamond, Star, Award, Zap } from "lucide-react";

const qualityTiers = {
  footwear: [
    { id: "surplus", name: "Factory Surplus", badge: "Authentic Grade", detail: "Overproduction or minor QC rejects. 100% original materials/labor.", quality: "100%", icon: <Star size={18} /> },
    { id: "ua", name: "Unauthorized Authentic", badge: "High-Tier", detail: "Produced in original factories using identical molds. Not authorized for retail.", quality: "98%", icon: <Zap size={18} /> },
    { id: "7a", name: "7A / Semi-UA", badge: "Mid-Tier", detail: "Highest visual accuracy. Uses synthetic blends instead of premium leathers.", quality: "85%", icon: <Award size={18} /> },
  ],
  watches: [
    { id: "superclone", name: "Super Clone", badge: "Master Grade", detail: "904L Steel & Cloned Swiss Movements (3235). Weight & sweep are 1:1.", quality: "99%", icon: <Diamond size={18} /> },
    { id: "aaa", name: "AAA Grade", badge: "Consumer Grade", detail: "Automatic Japanese movement with Sapphire glass. Reliable for daily wear.", quality: "90%", icon: <Watch size={18} /> },
  ],
  apparel: [
    { id: "master", name: "Master Quality", badge: "1:1 Grade", detail: "Correct GSM weight and embroidery density. Zero variance from original.", quality: "99%", icon: <Shirt size={18} /> },
    { id: "general", name: "General Rep", badge: "Entry Grade", detail: "Standard cotton blends. Correct print, lower fabric durability.", quality: "75%", icon: <Info size={18} /> },
  ]
};

export default function QualityProtocolPage() {
  const [activeDiv, setActiveDiv] = useState<keyof typeof qualityTiers>("footwear");

  return (
    <div className="bg-[#f8f9fa] text-[#1a1a1a] min-h-screen pb-24 font-sans selection:bg-black selection:text-white">
      
      {/* 1. ARCHITECTURAL HEADER */}
      <header className="pt-24 pb-20 px-6 max-w-6xl mx-auto text-center">
        <div className="inline-flex items-center gap-2 px-4 py-2 bg-white border border-black/5 rounded-full mb-8 shadow-sm">
          <ShieldCheck size={14} className="text-brand" />
          <span className="text-[10px] font-black uppercase tracking-widest">Manufacturing Intelligence</span>
        </div>
        <h1 className="text-6xl md:text-8xl font-black uppercase italic tracking-tighter leading-[0.8] mb-8">
          Quality <br /> <span className="text-brand">Protocol.</span>
        </h1>
        <p className="max-w-2xl mx-auto text-sm font-bold uppercase opacity-40 leading-relaxed italic">
          Transparency is our baseline. We categorize the global market into verified manufacturing tiers, from Factory Surplus to Master Clones.
        </p>
      </header>

      {/* 2. DIVISION SELECTOR (Pill Design) */}
      <section className="px-6 mb-16">
        <div className="max-w-md mx-auto bg-white/80 backdrop-blur-md p-1.5 rounded-[2rem] border border-black/5 shadow-xl flex gap-1">
          {Object.keys(qualityTiers).map((div) => (
            <button
              key={div}
              onClick={() => setActiveDiv(div as any)}
              className={`flex-1 py-4 rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest transition-all ${
                activeDiv === div ? "bg-black text-white shadow-lg" : "hover:bg-black/5 opacity-40 hover:opacity-100"
              }`}
            >
              {div}
            </button>
          ))}
        </div>
      </section>

      {/* 3. THE BENTO GRID (Deep Rounded Design) */}
      <main className="max-w-6xl mx-auto px-6 grid grid-cols-1 md:grid-cols-2 gap-6">
        {qualityTiers[activeDiv].map((tier, i) => (
          <div 
            key={tier.id}
            className={`relative p-10 rounded-[3.5rem] border border-black/5 shadow-sm transition-all duration-500 hover:shadow-2xl bg-white group ${
              i === 0 ? "md:col-span-2 bg-gradient-to-br from-white to-brand/5" : ""
            }`}
          >
            <div className="flex flex-col h-full justify-between gap-12">
              <div className="flex justify-between items-start">
                <div className="h-14 w-14 rounded-3xl bg-black text-white flex items-center justify-center group-hover:scale-110 transition-transform duration-500">
                  {tier.icon}
                </div>
                <div className="text-right">
                  <span className="block text-[10px] font-black uppercase opacity-30 tracking-widest">Tier Level</span>
                  <span className="text-2xl font-black italic text-brand tracking-tighter uppercase">{tier.badge}</span>
                </div>
              </div>

              <div className="space-y-4">
                <h3 className="text-4xl font-black uppercase italic tracking-tighter leading-none">{tier.name}</h3>
                <p className="text-sm font-bold opacity-60 uppercase italic leading-relaxed max-w-lg">{tier.detail}</p>
              </div>

              <div className="flex items-end justify-between border-t border-black/5 pt-8">
                <div className="space-y-1">
                  <p className="text-[8px] font-black uppercase opacity-30 tracking-widest">Accuracy Rating</p>
                  <p className="text-3xl font-black italic">{tier.quality}</p>
                </div>
                <button className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest group-hover:gap-4 transition-all">
                  In-Depth Analysis <Zap size={12} fill="currentColor" />
                </button>
              </div>
            </div>
          </div>
        ))}
      </main>

      {/* 4. SURPLUS EXPLAINER (Large Rounded Card) */}
      <section className="max-w-6xl mx-auto px-6 mt-16">
        <div className="bg-black text-white p-12 md:p-20 rounded-[4rem] relative overflow-hidden group">
          <div className="absolute top-0 right-0 p-10 opacity-10 group-hover:rotate-12 transition-transform duration-1000">
             <ShieldCheck size={300} />
          </div>
          <div className="relative z-10 grid grid-cols-1 lg:grid-cols-2 gap-12">
            <div className="space-y-6">
              <h2 className="text-5xl md:text-7xl font-black uppercase italic tracking-tighter leading-[0.8]">
                Surplus <br /> <span className="text-brand opacity-100">≠</span> <br /> Replica.
              </h2>
            </div>
            <div className="flex flex-col justify-center space-y-6">
              <p className="text-lg font-bold uppercase italic leading-tight opacity-80">
                Surplus inventory originates from the authorized production cycle. These are authentic items that entered the market through secondary channels due to logistics or overproduction. 
              </p>
              <div className="flex flex-wrap gap-4 pt-4 font-black uppercase text-[10px] tracking-widest">
                <span className="px-5 py-2 border border-white/20 rounded-full">100% Original Sourcing</span>
                <span className="px-5 py-2 border border-white/20 rounded-full">Factory Sanctioned</span>
              </div>
            </div>
          </div>
        </div>
      </section>
    </div>
  );
}